const http   = require('http');
const https  = require('https');
const fs     = require('fs');
const path   = require('path');
const os     = require('os');
const crypto = require('crypto');

const PORT       = 3000;
const HTTPS_PORT = 3443;

// PFX cert generated by PowerShell New-SelfSignedCertificate
const PFX_PATH = path.join(__dirname, 'server.pfx');
const PFX_PASS = 'qrft2026';
const MAX_MB  = 200;
const TTL_MS  = 15 * 60 * 1000; // file expires after 15 minutes

// In-memory store: token → { name, filePath, expires }
const store = {};

// Periodically remove expired files
setInterval(() => {
  const now = Date.now();
  for (const [token, entry] of Object.entries(store)) {
    if (now > entry.expires) {
      try { fs.unlinkSync(entry.filePath); } catch {}
      delete store[token];
    }
  }
}, 60_000);

function getLocalIP() {
  for (const ifaces of Object.values(os.networkInterfaces())) {
    for (const iface of ifaces) {
      if (iface.family === 'IPv4' && !iface.internal) return iface.address;
    }
  }
  return 'localhost';
}

function serveFile(res, filePath, contentType) {
  fs.readFile(filePath, (err, data) => {
    if (err) { res.writeHead(404); res.end('Not found'); return; }
    res.writeHead(200, { 'Content-Type': contentType });
    res.end(data);
  });
}

function jsonRes(res, status, obj) {
  res.writeHead(status, { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*' });
  res.end(JSON.stringify(obj));
}

function requestHandler(req, res) {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') { res.writeHead(204); res.end(); return; }

  // Serve UI — also serve sender/receiver by name
  if (req.method === 'GET' && (req.url === '/' || req.url === '/sender.html')) {
    serveFile(res, path.join(__dirname, 'sender.html'), 'text/html');
    return;
  }
  if (req.method === 'GET' && req.url === '/receiver.html') {
    serveFile(res, path.join(__dirname, 'receiver.html'), 'text/html');
    return;
  }
  if (req.method === 'GET' && req.url === '/fountain.js') {
    serveFile(res, path.join(__dirname, 'fountain.js'), 'application/javascript');
    return;
  }

  // Upload: POST /upload  body: { name, size, data (base64) }
  if (req.method === 'POST' && req.url === '/upload') {
    let body = Buffer.alloc(0);
    req.on('data', chunk => {
      body = Buffer.concat([body, chunk]);
      if (body.length > MAX_MB * 1024 * 1024 * 1.4) { // ~base64 overhead
        req.destroy();
        jsonRes(res, 413, { error: `File too large. Max ${MAX_MB} MB.` });
      }
    });
    req.on('end', () => {
      try {
        const { name, data } = JSON.parse(body.toString());
        if (!name || !data) return jsonRes(res, 400, { error: 'Missing name or data' });

        const safeName = path.basename(name).replace(/[^a-zA-Z0-9._\-]/g, '_');
        const token    = crypto.randomBytes(10).toString('hex');
        const filePath = path.join(os.tmpdir(), `qrft_${token}_${safeName}`);

        fs.writeFile(filePath, Buffer.from(data, 'base64'), (err) => {
          if (err) return jsonRes(res, 500, { error: 'Failed to save file' });

          store[token] = { name: safeName, filePath, expires: Date.now() + TTL_MS };

          const ip  = getLocalIP();
          const url = `http://${ip}:${PORT}/d/${token}`;
          jsonRes(res, 200, { url, token, expires: TTL_MS / 1000 });
          console.log(`📤 Uploaded: ${safeName}  →  ${url}`);
        });
      } catch (e) {
        jsonRes(res, 400, { error: 'Invalid request' });
      }
    });
    return;
  }

  // Download: GET /d/:token
  if (req.method === 'GET' && req.url.startsWith('/d/')) {
    const token = req.url.slice(3);
    const entry = store[token];

    if (!entry) {
      res.writeHead(404, { 'Content-Type': 'text/html' });
      res.end('<h2 style="font-family:sans-serif;text-align:center;margin-top:80px">❌ File not found or already downloaded.</h2>');
      return;
    }

    if (Date.now() > entry.expires) {
      try { fs.unlinkSync(entry.filePath); } catch {}
      delete store[token];
      res.writeHead(410, { 'Content-Type': 'text/html' });
      res.end('<h2 style="font-family:sans-serif;text-align:center;margin-top:80px">⏰ Link expired. Please share the file again.</h2>');
      return;
    }

    fs.stat(entry.filePath, (err, stat) => {
      if (err) { res.writeHead(404); res.end('File not found'); return; }

      res.writeHead(200, {
        'Content-Type': 'application/octet-stream',
        'Content-Disposition': `attachment; filename="${entry.name}"`,
        'Content-Length': stat.size,
      });

      const stream = fs.createReadStream(entry.filePath);
      stream.pipe(res);
      stream.on('close', () => {
        // Delete after first download
        try { fs.unlinkSync(entry.filePath); } catch {}
        delete store[token];
        console.log(`✅ Downloaded: ${entry.name}`);
      });
    });
    return;
  }

  // Status: GET /status/:token  — check if still available
  if (req.method === 'GET' && req.url.startsWith('/status/')) {
    const token = req.url.slice(8);
    const entry = store[token];
    if (!entry || Date.now() > entry.expires) {
      jsonRes(res, 200, { available: false });
    } else {
      jsonRes(res, 200, { available: true, remaining: Math.round((entry.expires - Date.now()) / 1000) });
    }
    return;
  }

  res.writeHead(404); res.end('Not found');
}

const server = http.createServer(requestHandler);

server.listen(PORT, '0.0.0.0', () => {
  const ip = getLocalIP();
  console.log('\n╔═══════════════════════════════════════════════════╗');
  console.log('║            QR File Transfer App                   ║');
  console.log('╠═══════════════════════════════════════════════════╣');
  console.log(`║  Sender (this PC):  http://localhost:${PORT}/            ║`);
  console.log(`║  Receiver (phone):  https://${ip}:${HTTPS_PORT}/   ║`);
  console.log('╚═══════════════════════════════════════════════════╝');
  console.log('\n📱 On the phone: open the https:// URL in Chrome');
  console.log('   First time: tap Advanced → Proceed to site (unsafe)\n');
});

// HTTPS server so Chrome on phone allows camera access
if (fs.existsSync(PFX_PATH)) {
  const tlsOptions = { pfx: fs.readFileSync(PFX_PATH), passphrase: PFX_PASS };
  https.createServer(tlsOptions, requestHandler).listen(HTTPS_PORT, '0.0.0.0');
} else {
  console.warn('⚠  server.pfx not found — HTTPS disabled. Phone camera may not work in Chrome.');
}
